import copy
import json
import re
from pathlib import Path

ROOT = Path('/Volumes/YSAigc/\u5267\u4f5c\u9879\u76ee/\u6211\u4e0d\u518d\u505a\u6559\u7236\u7684\u5927\u7801\u4eba\u5f62\u62b1\u6795')
TASK = ROOT / '\u5973\u4e3b\u4e3b\u52a8\u6d45\u543b_20261022'
AUTH = ROOT / '\u590d\u523b\u5168\u96c6_FormatC_V25_20261022'
TASK.mkdir(exist_ok=True)
base = json.loads((AUTH / '\u590d\u523b\u5168\u96c6_FormatC_V25_\u5168\u90e8\u63d0\u793a\u8bcd.json').read_text())
draft = copy.deepcopy(base)
patches = []

for suffix in ['json', 'md']:
    name = '\u590d\u523b\u5168\u96c6_FormatC_V25_\u5168\u90e8\u63d0\u793a\u8bcd.' + suffix
    (TASK / ('\u4fee\u6539\u524d_' + name)).write_bytes((AUTH / name).read_bytes())


def change(pos, shot, prefix, new):
    group = next(x for x in draft['groups'] if x['timeline_position'] == pos)
    lines = group['prompt'].splitlines()
    current = 0
    found = []
    for i, line in enumerate(lines):
        m = re.match(r'\u3010shot (\d+)', line)
        if m:
            current = int(m.group(1))
        if current == shot and line.startswith(prefix):
            found.append(i)
    assert len(found) == 1, (pos, shot, prefix, found)
    i = found[0]
    old = lines[i]
    assert old != new
    assert '\xa7ASSET:' not in old
    patches.append({'position': pos, 'shot': shot, 'old': old, 'new': new})
    lines[i] = new
    group['prompt'] = '\n'.join(lines)


g12 = next(x for x in draft['groups'] if x['timeline_position'] == 12)
old_lock = next(x for x in g12['prompt'].splitlines() if x.startswith('\u89d2\u8272\u3001\u573a\u666f\u53ca\u9053\u5177'))
new_lock = old_lock.replace(
    '\u4e00\u70b9\u5fc3\u52a8\u53ea\u5728\u5404\u955c\u5df2\u6709\u7684\u773c\u795e\u505c\u7559\u3001\u5782\u773c\u3001\u624b\u6307\u4e0e\u80a9\u9888\u8f7b\u5fae\u7d27\u5f20\u4e2d\u6d41\u9732\uff0c\u4e0d\u65b0\u589e\u52a8\u4f5c\u6216\u4e3b\u52a8\u4eb2\u543b\u3002',
    '\u5fc3\u52a8\u7531\u773c\u795e\u505c\u7559\u3001\u624b\u6307\u4e0e\u80a9\u9888\u8f7b\u5fae\u7d27\u5f20\u9010\u6b65\u663e\u9732\uff1b\u4ec5shot 3\u6309\u672c\u6b21\u8981\u6c42\u589e\u52a0\u5973\u4e3b\u4e3b\u52a8\u3001\u95ed\u5507\u6d45\u543b\u7537\u4e3b\u5634\u5507\u4e00\u6b21\u3002shot 1\u4ecd\u662f\u610f\u5916\u64e6\u8fc7\u4e0b\u5df4\uff0cshot 2\u4ecd\u662f\u5bf9\u89c6\u505c\u987f\uff0c\u4e24\u8005\u4e0d\u80fd\u63d0\u524d\u53d8\u6210\u4e3b\u52a8\u543b\uff1b\u7537\u4e3b\u5168\u7ec4\u4e0d\u4e3b\u52a8\u8fce\u543b\u6216\u8ffd\u543b\u3002')
change(12, 0, '\u89d2\u8272\u3001\u573a\u666f\u53ca\u9053\u5177', new_lock)
change(12, 0, '\u8282\u594f\u7ed3\u6784',
       '\u8282\u594f\u7ed3\u6784\uff08Beat Structure\uff09\uff1a\u7ec4\u578b\uff1a\u60c5\u7eea\u7ec4\uff5c3\u955c\uff5c\u517110.0s\uff1b\u4fdd\u75594.0 / 2.0 / 4.0\u79d2\u7684\u955c\u6570\u4e0e\u65f6\u957f\uff0c\u6700\u5f3a\u62cdshot 3\u3002shot 1\u662f\u610f\u5916\u64e6\u8fc7\u4e0b\u5df4\uff0cshot 2\u7559\u51fa\u53cc\u65b9\u6014\u4f4f\u7684\u505c\u987f\uff1bshot 3\u624d\u7531Eliza\u5728\u5fc3\u52a8\u4e0b\u4e3b\u52a8\u6d45\u543b\u7537\u4e3b\u5634\u5507\u4e00\u6b21\uff0c\u77ed\u63a5\u89e6\u540e\u5206\u5f00\u5230\u539f\u5c0f\u95f4\u8ddd\u3002\u8bef\u89e6\u4e0e\u4e3b\u52a8\u6d45\u543b\u662f\u524d\u540e\u5206\u660e\u7684\u4e24\u4e2a\u4e8b\u4ef6\uff1b\u540e\u8005\u4e3a\u672c\u6b21\u7528\u6237\u8865\u5145\uff0c\u4e0d\u5192\u5145\u590d\u523b\u6587\u4ef6\u539f\u52a8\u4f5c\u3002\u5973\u4e3b\u4e0d\u7b11\uff0c\u7537\u4e3b\u4e0d\u4e3b\u52a8\u8ffd\u8fd1\uff1b\u4e0b\u4e00\u7ec4\u624d\u7531\u5979\u56e0\u7f9e\u602f\u9000\u5f00\u3002')
